<template>
  <div
    class="fu-pill-multi-select"
    :class="[`fu-pill-multi-select--${size}`]"
    role="group"
    :style="typeformStyle"
  >
    <button
      v-for="opt in options"
      :key="opt.value"
      type="button"
      class="fu-pill fu-pill--multi"
      :class="{
        'is-selected': isSelected(opt.value),
        'is-readonly': readonly,
      }"
      :disabled="disabled"
      role="checkbox"
      :aria-checked="isSelected(opt.value)"
      @click="toggle(opt.value)"
    >
      <img
        v-if="typeof opt.icon === 'string'"
        :src="opt.icon"
        class="fu-pill__icon-img"
        alt=""
      />
      <component v-else-if="opt.icon" :is="opt.icon" :size="16" class="fu-pill__icon" />
      <span class="fu-pill__label">{{ opt.label }}</span>
      <span class="fu-pill__badge">
        <Check v-if="isSelected(opt.value)" :size="12" />
      </span>
    </button>
  </div>
</template>

<script setup lang="ts">
import { computed } from "vue";
import { Check } from "@lucide/vue";

type Size = "sm" | "md" | "lg";

interface Option {
  value: string | number;
  label: string;
  /** A Lucide icon component, OR an image URL string — both are supported. */
  icon?: any;
}

interface Props {
  modelValue?: (string | number)[];
  options: Option[];
  size?: Size;
  disabled?: boolean;
  readonly?: boolean;

  font?: string;
  fontSize?: string;
  color?: string;
}

const props = withDefaults(defineProps<Props>(), {
  modelValue: () => [],
  size: "md",
  disabled: false,
  readonly: false,
  font: undefined,
  fontSize: undefined,
  color: undefined,
});

const emit = defineEmits<{
  (e: "update:modelValue", value: (string | number)[]): void;
}>();

function isSelected(value: string | number) {
  return props.modelValue.includes(value);
}

function toggle(value: string | number) {
  if (props.disabled || props.readonly) return;
  const next = isSelected(value)
    ? props.modelValue.filter((v) => v !== value)
    : [...props.modelValue, value];
  emit("update:modelValue", next);
}

const typeformStyle = computed(() => ({
  ...(props.font ? { "--fu-typeform-font": props.font } : {}),
  ...(props.fontSize ? { "--fu-typeform-font-size": props.fontSize } : {}),
  ...(props.color ? { "--fu-typeform-color": props.color } : {}),
}));
</script>

