<template>
  <FusionModal :isVisible="isVisible" title="Signature" size="md" @close="$emit('close')">
    <FusionTab
      defaultActiveDesktop="draw"
      defaultActiveMobile="draw"
      :tabs="tabs"
      @tab-change="activeTab = $event"
    >
      <!-- Draw -->
      <template #draw>
        <div class="sig-draw">
          <div class="sig-draw__toolbar">
            <button class="sig-draw__clear" @click="clearCanvas">Clear</button>
            <div class="sig-draw__colors">
              <button
                v-for="c in PEN_COLORS"
                :key="c"
                class="sig-draw__swatch"
                :class="{ active: penColor === c }"
                :style="{ backgroundColor: c }"
                @click="penColor = c"
              />
            </div>
          </div>
          <div ref="canvasWrapRef" class="sig-draw__pad">
            <canvas
              ref="canvasRef"
              @mousedown="startDraw"
              @mousemove="draw"
              @mouseup="stopDraw"
              @mouseleave="stopDraw"
              @touchstart.prevent="startDraw"
              @touchmove.prevent="draw"
              @touchend.prevent="stopDraw"
            />
            <div class="sig-draw__line" />
          </div>
        </div>
      </template>

      <!-- Type -->
      <template #type>
        <div class="sig-type">
          <FusionTextInput
            v-model="typedName"
            label="Type your name"
            placeholder="Your full name"
            size="md"
            variant="outline"
            formWrapperWidth="100%"
          />
          <div class="sig-type__preview">{{ typedName || "Your signature" }}</div>
        </div>
      </template>

      <!-- My Signature -->
      <template #mySignature>
        <div class="sig-saved">
          <template v-if="savedSignature">
            <img
              v-if="savedSignature.dataUrl"
              :src="savedSignature.dataUrl"
              alt="Saved signature"
              class="sig-saved__preview"
            />
            <div v-else class="sig-saved__typed">{{ savedSignature.text }}</div>
          </template>
          <p v-else class="sig-saved__empty">
            No saved signature yet — draw or type one first and it'll be remembered here
            next time.
          </p>
        </div>
      </template>
    </FusionTab>

    <template #footer>
      <div class="sig-footer">
        <p class="sig-consent">
          By electronically signing this document, I agree that my signature and initials
          are the equivalent of my handwritten signature and are considered originals on
          all documents, including legally binding contracts.
        </p>

        <div v-if="showHint" class="sig-hint">
          To make your signature valid, please use at least two alphanumeric characters or
          continue signing.
        </div>

        <div class="sig-actions">
          <FusionButton variant="outline" text="Cancel" @click="$emit('close')" />
          <FusionButton
            variant="success"
            text="Accept and sign"
            :disabled="!isValid"
            @click="accept"
          />
        </div>
      </div>
    </template>
  </FusionModal>
</template>

<script setup>
import { ref, computed, onMounted, onBeforeUnmount, nextTick, watch } from "vue";
import FusionModal from "../../modal/FusionModal.vue";
import FusionTab from "../../tabs/FusionTab.vue";
import FusionTextInput from "../../TextInput/FusionTextInput.vue";
import FusionButton from "../../button/FusionButton.vue";

const props = defineProps({
  isVisible: { type: Boolean, default: false },
  // Who this signature is being captured for — the recipient the field is
  // assigned to, resolved by the caller (FieldOverlay.vue / PreviewRender.vue
  // both already have store.contractRecipients to look this up from). Binds
  // the signer's identity onto the signed payload, same as PandaDoc/DocuSign
  // stamping "Signed by <name>" rather than just storing an anonymous doodle.
  signerName: { type: String, default: "" },
});
const emit = defineEmits(["close", "signed"]);

const tabs = [
  { key: "draw", title: "Draw" },
  { key: "type", title: "Type" },
  { key: "mySignature", title: "My Signature" },
];
const activeTab = ref("draw");

const STORAGE_KEY = "skkido_saved_signature";
const PEN_COLORS = ["#111827", "#2563eb", "#dc2626"];

// ── Draw ──────────────────────────────────────────────────────────────────
const canvasRef = ref(null);
const canvasWrapRef = ref(null);
const isDrawing = ref(false);
const hasDrawn = ref(false);
const penColor = ref(PEN_COLORS[0]);

function sizeCanvas() {
  const canvas = canvasRef.value;
  const wrap = canvasWrapRef.value;
  if (!canvas || !wrap) return;
  const rect = wrap.getBoundingClientRect();
  const ratio = window.devicePixelRatio || 1;
  canvas.width = rect.width * ratio;
  canvas.height = rect.height * ratio;
  canvas.style.width = rect.width + "px";
  canvas.style.height = rect.height + "px";
  canvas.getContext("2d").scale(ratio, ratio);
}

function pointFromEvent(e) {
  const rect = canvasRef.value.getBoundingClientRect();
  const point = e.touches?.[0] ?? e;
  return { x: point.clientX - rect.left, y: point.clientY - rect.top };
}

function startDraw(e) {
  isDrawing.value = true;
  const ctx = canvasRef.value.getContext("2d");
  const { x, y } = pointFromEvent(e);
  ctx.beginPath();
  ctx.moveTo(x, y);
}

function draw(e) {
  if (!isDrawing.value) return;
  const ctx = canvasRef.value.getContext("2d");
  const { x, y } = pointFromEvent(e);
  ctx.strokeStyle = penColor.value;
  ctx.lineWidth = 2.5;
  ctx.lineCap = "round";
  ctx.lineTo(x, y);
  ctx.stroke();
  hasDrawn.value = true;
}

function stopDraw() {
  isDrawing.value = false;
}

function clearCanvas() {
  const canvas = canvasRef.value;
  if (!canvas) return;
  const ratio = window.devicePixelRatio || 1;
  canvas.getContext("2d").clearRect(0, 0, canvas.width / ratio, canvas.height / ratio);
  hasDrawn.value = false;
}

// ── Type ──────────────────────────────────────────────────────────────────
const typedName = ref("");

// ── My Signature (remembered locally, per browser — no backend for this yet) ──
const savedSignature = ref(null);
function loadSaved() {
  try {
    savedSignature.value = JSON.parse(localStorage.getItem(STORAGE_KEY) || "null");
  } catch {
    savedSignature.value = null;
  }
}
function persistAsDefault(sig) {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(sig));
  } catch {
    // storage unavailable (private mode, quota, etc.) — non-fatal, just won't be remembered
  }
  savedSignature.value = sig;
}

// ── Validity per tab ──────────────────────────────────────────────────────
const isValid = computed(() => {
  if (activeTab.value === "draw") return hasDrawn.value;
  if (activeTab.value === "type") return typedName.value.trim().length >= 2;
  if (activeTab.value === "mySignature") return !!savedSignature.value;
  return false;
});
const showHint = computed(
  () => (activeTab.value === "draw" || activeTab.value === "type") && !isValid.value
);

function accept() {
  if (!isValid.value) return;
  let payload = null;
  if (activeTab.value === "draw") {
    payload = { type: "drawn", dataUrl: canvasRef.value.toDataURL("image/png") };
  } else if (activeTab.value === "type") {
    payload = { type: "typed", text: typedName.value.trim() };
  } else if (activeTab.value === "mySignature") {
    payload = savedSignature.value;
  }
  if (!payload) return;
  if (activeTab.value !== "mySignature") persistAsDefault(payload);
  emit("signed", {
    ...payload,
    signerName: props.signerName,
    signedOn: new Date().toISOString(),
  });
  emit("close");
}

let resizeObserver = null;
onMounted(() => {
  loadSaved();
  nextTick(sizeCanvas);
  resizeObserver = new ResizeObserver(() => sizeCanvas());
  if (canvasWrapRef.value) resizeObserver.observe(canvasWrapRef.value);
});
onBeforeUnmount(() => {
  resizeObserver?.disconnect();
});

watch(
  () => props.isVisible,
  (v) => {
    if (v) {
      activeTab.value = "draw";
      hasDrawn.value = false;
      typedName.value = "";
      loadSaved();
      nextTick(() => {
        sizeCanvas();
        clearCanvas();
      });
    }
  }
);
</script>

