<template>
  <div class="fu-textarea-wrapper">
    <label v-if="label" class="fu-textarea-label">
      {{ label }}
      <span v-if="required" class="fu-textarea-required">*</span>
    </label>
    <textarea
      v-bind="$attrs"
      ref="textareaRef"
      class="fu-textarea fu-form-control"
      :class="[
        `fu-textarea--${size}`,
        { 'fu-textarea--error': error },
        variant ? `fu-textarea--${variant}` : null,
      ]"
      :style="typeformStyle"
      :placeholder="placeholder"
      :disabled="disabled"
      :readonly="readonly"
      :rows="rows"
      :required="required"
      v-model="innerValue"
      @input="autoResize"
    ></textarea>
    <span v-if="error" class="fu-textarea-error">{{ error }}</span>
    <span v-else-if="variant === 'typeform'" class="fu-textarea-hint">
      <template v-if="isMac">
        <strong>Shift ⇧</strong> + <strong>Return ↵</strong> to make a line break
      </template>
      <template v-else>
        <strong>Shift</strong> + <strong>Enter</strong> to make a line break
      </template>
    </span>
  </div>
</template>

<script setup lang="ts">
import { ref, watch, computed, nextTick, onMounted } from "vue";

interface Props {
  modelValue?: string;
  label?: string;
  variant?: "subtle" | "outline" | "plain" | "typeform";
  placeholder?: string;
  size?: "sm" | "md" | "lg";
  disabled?: boolean;
  readonly?: boolean;
  error?: string | null;
  rows?: number;
  required?: boolean;

  /* TYPEFORM VARIANT STYLING */
  font?: string;
  color?: string;
  fontSize?: string;
}

const props = withDefaults(defineProps<Props>(), {
  modelValue: "",
  label: "",
  placeholder: "",
  size: "sm",
  disabled: false,
  readonly: false,
  error: null,
  rows: 1,
  required: false,
  variant: "subtle",
  font: undefined,
  color: undefined,
  fontSize: undefined,
});

const emit = defineEmits<{
  (e: "update:modelValue", value: string): void;
}>();

const innerValue = ref(props.modelValue);
const textareaRef = ref<HTMLTextAreaElement | null>(null);

const isMac = computed(() => {
  if (typeof navigator === "undefined") return false;
  return /Mac|iPhone|iPad|iPod/.test(navigator.userAgent);
});

watch(innerValue, (val) => emit("update:modelValue", val));
watch(
  () => props.modelValue,
  (val) => {
    innerValue.value = val;
    nextTick(autoResize);
  }
);

const typeformStyle = computed(() => {
  if (props.variant !== "typeform") return {};
  return {
    ...(props.font ? { "--fu-typeform-font": props.font } : {}),
    ...(props.color ? { "--fu-typeform-color": props.color } : {}),
    ...(props.fontSize ? { "--fu-typeform-font-size": props.fontSize } : {}),
  };
});

function autoResize() {
  if (props.variant !== "typeform" || !textareaRef.value) return;
  const el = textareaRef.value;
  el.style.height = "auto";
  el.style.height = `${Math.max(el.scrollHeight, 60)}px`;
}

onMounted(() => {
  nextTick(autoResize);
});
</script>
<style scoped lang="scss">
@use "./FusionTextArea.scss";
</style>
