<template>
  <button
    type="button"
    class="fu-switch"
    :class="[{ 'fu-switch--checked': modelValue, disabled }, sizeClass]"
    role="switch"
    :aria-checked="modelValue"
    :disabled="disabled"
    @click="toggle"
  >
    <span class="fu-switch__thumb"></span>
  </button>
</template>

<script lang="ts" setup>
import { computed } from "vue"

interface Props {
  modelValue: boolean
  disabled?: boolean
  size?: "sm" | "md" | "lg"
}

const props = defineProps<Props>()
const emit = defineEmits<{ (e: "update:modelValue", value: boolean): void }>()

function toggle() {
  if (props.disabled) return
  emit("update:modelValue", !props.modelValue)
}

const sizeClass = computed(() => {
  switch (props.size) {
    case "sm":
      return "fu-switch--sm"
    case "lg":
      return "fu-switch--lg"
    default:
      return "fu-switch--md"
  }
})
</script>

<style scoped lang="scss">
.fu-switch {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: flex-start;
  width: rem-calc(38);
  height: rem-calc(22);
  border-radius: rem-calc(9999);
  background-color: #e5e7eb; /* gray-200 */
  cursor: pointer;
  transition: background-color 0.2s ease, box-shadow 0.2s ease;
  border: none;
  outline: none;
}

.fu-switch__thumb {
  position: absolute;
  top: rem-calc(2);
  left: rem-calc(2);
  width: rem-calc(18);
  height: rem-calc(18);
  background-color: white;
  border-radius: 50%;
  transition: transform 0.2s ease;
  box-shadow: 0 rem-calc(1) rem-calc(2) rgba(0, 0, 0, 0.15);
}

.fu-switch--checked {
  background-color: #2563eb; /* blue-600 */
}
.fu-switch--checked .fu-switch__thumb {
  transform: translateX(rem-calc(16));
}

/* Disabled */
.fu-switch.disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

/* Sizes */
.fu-switch--sm {
  width: rem-calc(30);
