<template>
  <Teleport to="body">
    <div v-if="visible.size > 0" class="fu-alert-stack">
      <TransitionGroup name="fu-alert-strip" tag="div" class="fu-alert-stack__inner">
        <div
          v-for="alert in activeAlerts"
          :key="alert.id"
          :class="['fu-alert-strip', `fu-alert-strip--${alert.type}`]"
        >
          <span class="fu-alert-strip__dot" />

          <div class="fu-alert-strip__body">
            <span class="fu-alert-strip__msg">{{ alert.message }}</span>
            <span v-if="alert.sub" class="fu-alert-strip__sub">{{ alert.sub }}</span>
          </div>

          <div class="fu-alert-strip__actions">
            <a
              v-if="alert.cta"
              :href="alert.cta.href ?? '#'"
              class="fu-alert-strip__cta"
              @click.prevent="alert.cta.action ? alert.cta.action() : null"
            >
              {{ alert.cta.label }}
            </a>
            <button
              v-if="alert.dismissible !== false"
              class="fu-alert-strip__dismiss"
              title="Dismiss"
              @click="dismiss(alert)"
            >
              <X :size="13" :stroke-width="2.5" />
            </button>
          </div>
        </div>
      </TransitionGroup>
    </div>
  </Teleport>
</template>

<script setup lang="ts">
import { ref, computed, onMounted } from "vue";
import { X } from "@lucide/vue";

export interface AlertItem {
  /** Unique id — also used as the localStorage key when `storageKey` is absent */
  id: string;
  /** Visual type driving colour */
  type: "info" | "warning" | "outage" | "trial";
  /** Main message line */
  message: string;
  /** Optional secondary line */
  sub?: string;
  /**
   * Whether the user can dismiss this alert.
   * Defaults to true. Set to false for critical outages that must stay
   * until the source (CMS / store) removes the alert from the list.
   */
  dismissible?: boolean;
  /**
   * Optional call-to-action button.
   * Provide `href` for a link or `action` for a callback (or both).
   */
  cta?: { label: string; href?: string; action?: () => void };
  /**
   * Whether the dismissal persists across page loads.
   *
   * - `true` (default for CMS alerts) → saved in `localStorage`.
   *   The alert stays hidden until you change its `id` or the user clears storage.
   * - `false` (recommended for trial alerts) → saved in `sessionStorage`.
   *   The alert reappears every new browser session, reminding the user each time
   *   they open the app — without being permanently ignorable.
   */
  persistent?: boolean;
  /**
   * Override the storage key. Defaults to `fu-alert-dismissed-${id}`.
   */
  storageKey?: string;
}

const props = defineProps<{
  alerts: AlertItem[];
}>();

const STORAGE_PREFIX = "fu-alert-dismissed-";

function resolvedKey(alert: AlertItem) {
  return alert.storageKey ?? `${STORAGE_PREFIX}${alert.id}`;
}

function getStorage(alert: AlertItem): Storage | null {
  try {
    // persistent defaults to true; only false opts into sessionStorage
    return alert.persistent === false ? sessionStorage : localStorage;
  } catch {
    return null;
  }
}

const dismissed = ref<Set<string>>(new Set());

onMounted(() => {
  const next = new Set<string>();
  for (const alert of props.alerts) {
    if (alert.dismissible === false) continue;
    const storage = getStorage(alert);
    if (storage?.getItem(resolvedKey(alert)) === "1") {
      next.add(alert.id);
    }
  }
  dismissed.value = next;
});

const visible = computed(() => {
  const s = new Set<string>();
  for (const a of props.alerts) {
    if (!dismissed.value.has(a.id)) s.add(a.id);
  }
  return s;
});

const activeAlerts = computed(() =>
  props.alerts.filter((a) => !dismissed.value.has(a.id))
);

function dismiss(alert: AlertItem) {
  dismissed.value = new Set([...dismissed.value, alert.id]);
  try {
    getStorage(alert)?.setItem(resolvedKey(alert), "1");
  } catch {}
}
</script>

